import json
import csv
import pandas as pd
from datetime import datetime

# ---------- Read sources ----------
with open('/data/source_a/users.json') as f:
    data_a = json.load(f)

with open('/data/source_b/users.csv') as f:
    data_b = list(csv.DictReader(f))

data_c = pd.read_parquet('/data/source_c/users.parquet').to_dict(orient='records')

# ---------- Field mappings ----------
map_a = {'id':'user_id','full_name':'name','email':'email','registration_date':'created_date','status':'status'}
map_b = {'user_id':'user_id','name':'name','email_address':'email','created_at':'created_date','is_active':'status'}
map_c = {'userId':'user_id','userName':'name','email':'email','joined':'created_date','active':'status'}

def normalize_record(rec, mapping):
    out = {}
    for k, v in rec.items():
        if k in mapping:
            out[mapping[k]] = v
    return out

records = {
    'source_a': [normalize_record(r, map_a) for r in data_a],
    'source_b': [normalize_record(r, map_b) for r in data_b],
    'source_c': [normalize_record(r, map_c) for r in data_c],
}
priority = ['source_a','source_b','source_c']
fields = ['name','email','created_date','status']

# group by user_id
by_user = {}
for src in priority:
    for rec in records[src]:
        uid = int(rec['user_id'])
        by_user.setdefault(uid, {})[src] = rec

def fmt_date(v):
    if v is None or v == '':
        return None
    s = str(v)
    try:
        return datetime.strptime(s[:10], '%Y-%m-%d').strftime('%Y-%m-%d')
    except ValueError:
        return s

def to_str(v):
    if v is None or v == '':
        return None
    if isinstance(v, bool):
        return 'true' if v else 'false'
    return str(v)

def norm_for_compare(v):
    if v is None or v == '':
        return None
    if isinstance(v, bool):
        return 'true' if v else 'false'
    return str(v)

merged_rows = []
conflicts = []

for uid in sorted(by_user.keys()):
    srcs = by_user[uid]
    row = {'user_id': uid}
    for field in fields:
        present = [s for s in priority if s in srcs and field in srcs[s] and srcs[s][field] not in (None, '')]
        selected = srcs[present[0]][field] if present else None
        if field == 'created_date':
            row[field] = fmt_date(selected)
        elif field == 'status':
            row[field] = to_str(selected)
        else:
            row[field] = None if selected is None else str(selected)
        if len(present) >= 2:
            vals = {s: srcs[s][field] for s in present}
            distinct = set(norm_for_compare(srcs[s][field]) for s in present)
            if len(distinct) > 1:
                if field == 'created_date':
                    sel = fmt_date(selected)
                elif field == 'status':
                    sel = to_str(selected)
                else:
                    sel = selected
                conflicts.append({
                    'user_id': uid,
                    'field': field,
                    'values': vals,
                    'selected': sel,
                })
    merged_rows.append(row)

df = pd.DataFrame(merged_rows, columns=['user_id','name','email','created_date','status'])
df['user_id'] = df['user_id'].astype('int64')
for c in ['name','email','created_date','status']:
    df[c] = df[c].astype('string')
df.to_parquet('/app/merged_users.parquet', index=False)

report = {'total_conflicts': len(conflicts), 'conflicts': conflicts}
with open('/app/conflicts.json','w') as f:
    json.dump(report, f, indent=2)

print(df)
print(json.dumps(report, indent=2))
